      "key_points": [
        "Bow and set the distance: uke takes the first right-side rear guard in zenkutsu dachi, and the form runs blocks and strikes, then joint locks, then chokes and throws.",
        "First two pairs: Hidari Nagashi Uke with Migi Haito Uchi, then Migi Nagashi Uke with Hidari Teisho Uchi.",
        "Next two pairs: Migi Sankyo into Hara Gatame, then Hidari Ude Garami.",
        "Final four pairs: Migi Hadaka Jime, Migi Okuri Eri Jime, Migi O Soto Otoshi and Migi Ko Soto Gari; close with the bow."
      ],
      "key_points_es": [
        "Saluda y fija la distancia: uke adopta la primera guardia trasera derecha en zenkutsu dachi, y la forma recorre bloqueos y golpes, después luxaciones y por último estrangulaciones y proyecciones.",
        "Primeras dos parejas: Hidari Nagashi Uke con Migi Haito Uchi, luego Migi Nagashi Uke con Hidari Teisho Uchi.",
        "Siguientes dos parejas: Migi Sankyo hacia Hara Gatame, luego Hidari Ude Garami.",
        "Últimas cuatro parejas: Migi Hadaka Jime, Migi Okuri Eri Jime, Migi O Soto Otoshi y Migi Ko Soto Gari; cierra con la reverencia."
      ],
      "mistakes": [
        "Rushing the transitions between attack and defence.",
        "Dropping the guard or losing posture during the locks and chokes.",
        "Applying pressure before controlling the position, or throwing without kuzushi."
      ],
      "mistakes_es": [
        "Ir con prisa en las transiciones entre ataque y defensa.",
        "Bajar la guardia o perder la postura durante las luxaciones y estrangulaciones.",
        "Aplicar presión antes de controlar la posición o proyectar sin kuzushi."
      ],
